-- ------------------------------------------------------------
-- 2. Bienes
--
--    Se insertan de a uno dentro de un bucle, y no con un INSERT masivo,
--    porque generar_codigo() consulta el maximo correlativo de la categoria:
--    en un INSERT de varias filas todas leerian el mismo maximo y chocarian
--    contra el unique de codigo.
-- ------------------------------------------------------------
do $$
declare
  r        record;
  v_id     bigint;
  v_total  int := 0;
begin
  if exists (select 1 from public.activos where creado_por = 'MIGRACION-COMPUTACION-2026') then
    raise exception 'La migracion ya fue ejecutada. Para rehacerla, borre primero los bienes cuyo creado_por sea MIGRACION-COMPUTACION-2026';
