    ) as t(orden, categoria, denominacion, marca, modelo, caracteristicas,
           ubicacion, responsable, estado, observaciones)
    order by orden
  loop
    insert into public.activos (
      categoria, denominacion, marca, modelo, caracteristicas,
      ubicacion, responsable, estado, procedencia, valor,
      observaciones, verificacion, creado_por
    ) values (
      r.categoria, r.denominacion, r.marca, r.modelo, r.caracteristicas,
      r.ubicacion, r.responsable, r.estado, 'Sin dato', 0,
      r.observaciones, 'Pendiente', 'MIGRACION-COMPUTACION-2026'
    ) returning id into v_id;

    insert into public.movimientos (activo_id, tipo, detalle, usuario)
    values (v_id, 'ALTA',
            'Alta por migracion del inventario de equipos de computacion (PDF de Sistemas)',
            'MIGRACION-COMPUTACION-2026');

    v_total := v_total + 1;
  end loop;

  raise notice 'Bienes migrados: %', v_total;
end $$;

-- ------------------------------------------------------------
-- 3. Comprobacion
-- ------------------------------------------------------------
select c.nombre as categoria, count(*) as bienes
  from public.activos a
  join public.categorias c on c.codigo = a.categoria
 where a.creado_por = 'MIGRACION-COMPUTACION-2026'
 group by c.nombre
 order by bienes desc;

